import{_ as e,o as i,c as n,ag as o}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"pl/nay-lib/index.md","filePath":"pl/nay-lib/index.md"}'),r={name:"pl/nay-lib/index.md"};function s(t,a,l,p,c,d){return i(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p><code>nay_lib</code> to wspólna biblioteka, na której działa każdy skrypt Nayretis. Dostajesz ją przy każdym zakupie, instalujesz raz i korzysta z niej każdy dodany skrypt Nayretis.</p><h2 id="co-daje" tabindex="-1">Co daje <a class="header-anchor" href="#co-daje" aria-label="Permalink to &quot;Co daje&quot;">​</a></h2><ul><li><strong>Jeden panel ustawień</strong>, <code>/nay</code>, dla wszystkich skryptów Nayretis. Ustawienia są przechowywane w bazie danych i stosowane u wszystkich graczy zaraz po zapisaniu. Zobacz <a href="/pl/nay-lib/panel">panel /nay</a>.</li><li><strong>Uprawnienia</strong> przez ACE oraz identyfikatory Discord, Steam, FiveM lub license. Zobacz <a href="/pl/nay-lib/permissions">Uprawnienia</a>.</li><li><strong>Sześć języków</strong>: angielski, francuski, hiszpański, portugalski, polski i niemiecki. W razie braku tłumaczenia wyświetlany jest tekst angielski.</li><li><strong>Bridge frameworków</strong>: ESX Legacy, QBCore, QBox i ox_core wykrywane automatycznie, razem z ich ekwipunkami, targetami i powiadomieniami. Zobacz <a href="/pl/bridge/">Bridge</a>.</li><li><strong>API HTTP</strong> dla Twojej strony, panelu lub bota Discord, domyślnie wyłączone. Zobacz <a href="/pl/nay-lib/api">API HTTP</a>.</li><li><strong>Webhooki</strong>, w tym wiadomości na Discordzie, dla zdarzeń skryptów. Zobacz <a href="/pl/nay-lib/webhooks">Webhooki</a>.</li><li><strong>Dziennik zmian</strong> obejmujący każdą zmianę wprowadzoną w grze, z konsoli lub przez API. Zobacz <a href="/pl/nay-lib/audit">Dziennik zmian</a>.</li><li>Powiadomienia, podpowiedzi tekstowe i paski postępu Nayretis, wspólne dla wszystkich skryptów.</li></ul><h2 id="wymagania-i-kolejnosc-uruchamiania" tabindex="-1">Wymagania i kolejność uruchamiania <a class="header-anchor" href="#wymagania-i-kolejnosc-uruchamiania" aria-label="Permalink to &quot;Wymagania i kolejność uruchamiania&quot;">​</a></h2><p>Jedyną zależnością jest <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Uruchamiaj <code>nay_lib</code> po zasobach frameworka, ekwipunku i targetu, a przed każdym skryptem Nayretis:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>Tabele tworzą się przy pierwszym uruchomieniu. Opcje serwera ustawiane w <code>server.cfg</code> opisuje strona <a href="/pl/nay-lib/convars">Convary</a>.</p>`,8)])])}const u=e(r,[["render",s]]);export{k as __pageData,u as default};
